from collections import deque, Counter
def f(g):
    h=len(g); w=len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=max(cnt,key=cnt.get)   # most common = outer/background
    other=[c for c in cnt if c!=bg]
    fill=min(other,key=lambda c:cnt[c]) if other else None
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==fill and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==fill and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and g[ni][nj]==fill:
                seen[ni][nj]=True; q.append((ni,nj))
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==fill and not seen[i][j]: out[i][j]=4
    return out
