def f(g):
    h=len(g); w=len(g[0])
    cnt=Counter(x for row in g for x in row)
    # frame color: one of the top counts whose cells include border; fill = other main color
    # pick the color among the top two counts that appears on the border most frequently
    bg=cnt.most_common()[0][0]
    order=[x[0] for x in cnt.most_common()]
    candidates=[c for c in order if c!=bg][:2]
    def ntouch(c): return sum(row[i] in (0,c) and (i in (0,h-1) or j in (0,w-1)) for i,row in enumerate(g) for j,x in enumerate(row) if x==c)
    fc=max(candidates,key=lambda c:ntouch(c))
    out=[r[:] for r in g]
    for c,cells in comps(g):
        if c==fc and not any(i in(0,h-1) or j in(0,w-1) for i,j in cells):
            for i,j in cells: out[i][j]=4
    return out

